export const GRID_META = {
  no2: { label: "NO2 (relative index, x1e9 mol/m^2)", unit: "idx", source: "Sentinel-5P TROPOMI 2025" },
  so2: { label: "SO2 (relative index, x1e9 mol/m^2)", unit: "idx", source: "Sentinel-5P TROPOMI 2025" },
  co: { label: "CO (relative index, x1e3 mol/m^2)", unit: "idx", source: "Sentinel-5P TROPOMI 2025" },
  o3: { label: "O3 tropospheric (relative index, x1e3 mol/m^2)", unit: "idx", source: "Sentinel-5P TROPOMI 2025" },
  lst: { label: "Land Surface Temperature", unit: "C", source: "MODIS MOD11A2 2025" },
  nightlights: { label: "Night Light Radiance (economic activity proxy)", unit: "nW/cm2/sr", source: "VIIRS DNB, last 12 months" },
  builtup: { label: "Built-up Surface (% of 100m cell)", unit: "%", source: "GHSL P2023A, 2020 (observed)" },
  water: { label: "Surface Water Occurrence (1984-2021)", unit: "%", source: "JRC Global Surface Water v1.4" },
  elevation: { label: "Elevation", unit: "m", source: "SRTM 30m" },
  landcover: { label: "Land Cover Class (0=water,1=trees,2=grass,3=flooded_veg,4=crops,5=shrub,6=built,7=bare,8=snow)", unit: "class", source: "Dynamic World V1, last 12mo" },
  treecover: { label: "Tree Canopy Cover (year 2000 baseline)", unit: "%", source: "Hansen Global Forest Change" },
  forestloss: { label: "Forest Loss since 2000 (% of cell)", unit: "%", source: "Hansen Global Forest Change 2000-2025" },
  population: { label: "Population (estimated people per 100m cell)", unit: "people", source: "WorldPop community catalog, 2024" },
};

function nearestIndex(arr, val) {
  let bi = 0, bd = Infinity;
  for (let i = 0; i < arr.length; i++) {
    const d = Math.abs(arr[i] - val);
    if (d < bd) { bd = d; bi = i; }
  }
  return bi;
}

// Generic lookup: gridObj = {lats, lons, grid}
export function lookupGridValue(gridObj, lat, lng) {
  if (!gridObj) return null;
  const iL = nearestIndex(gridObj.lats, lat);
  const iG = nearestIndex(gridObj.lons, lng);
  const v = gridObj.grid[iL]?.[iG];
  return (v === null || v === undefined) ? null : v;
}

const ALL_GRIDS = {
  no2: NO2_GRID,
  so2: SO2_GRID,
  co: CO_GRID,
  o3: O3_GRID,
  lst: LST_GRID,
  nightlights: NIGHTLIGHTS_GRID,
  builtup: BUILTUP_GRID,
  water: WATER_GRID,
  elevation: ELEVATION_GRID,
  landcover: LANDCOVER_GRID,
  treecover: TREECOVER_GRID,
  forestloss: FORESTLOSS_GRID,
  population: POPULATION_GRID,
};

// Look up every One Health environmental layer at once for a coordinate.
export function lookupOneHealthLayers(lat, lng) {
  const out = {};
  for (const key of Object.keys(ALL_GRIDS)) {
    out[key] = lookupGridValue(ALL_GRIDS[key], lat, lng);
  }
  return out;
}

export const LANDCOVER_LABELS = {
  0: 'Water', 1: 'Trees', 2: 'Grass', 3: 'Flooded vegetation',
  4: 'Crops', 5: 'Shrub & scrub', 6: 'Built area', 7: 'Bare ground', 8: 'Snow/ice',
};
